import{_ as i,C as n,o as r,c as d,j as t,a,b as l,w as s,E as c,a4 as h,a3 as p}from"./chunks/framework.DhF4LrUq.js";const b=JSON.parse('{"title":"Release lifecycle","description":"The release lifecycle - states from DRAFT to COMPLETED, what each crossing demands, and the frozen release manifest.","frontmatter":{"description":"The release lifecycle - states from DRAFT to COMPLETED, what each crossing demands, and the frozen release manifest."},"headers":[],"relativePath":"concepts/release-lifecycle.md","filePath":"concepts/release-lifecycle.md"}'),f={name:"concepts/release-lifecycle.md"};function m(g,e,u,A,E,T){const o=n("Mermaid");return r(),d("div",null,[e[1]||(e[1]=t("h1",{id:"release-lifecycle",tabindex:"-1"},[a("Release lifecycle "),t("a",{class:"header-anchor",href:"#release-lifecycle","aria-label":'Permalink to "Release lifecycle"'},"​")],-1)),e[2]||(e[2]=t("p",null,"A release is a controlled distribution event: one version of one application, a set of target tenants (optionally narrowed to tester groups), a starting ring, and one artifact per platform. Nothing reaches a tester until a release says so — and every step a release takes is explicit, ordered, and recorded.",-1)),e[3]||(e[3]=t("p",null,"One release exists per application and version. A version can exist without a release; releases reference versions, never the reverse.",-1)),e[4]||(e[4]=t("h2",{id:"the-state-machine",tabindex:"-1"},[a("The state machine "),t("a",{class:"header-anchor",href:"#the-state-machine","aria-label":'Permalink to "The state machine"'},"​")],-1)),e[5]||(e[5]=t("p",null,"A release moves through exactly this machine — nothing else is legal, and the table is exhaustive:",-1)),(r(),l(h,null,{default:s(()=>[c(o,{id:"mermaid-15",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20DRAFT%20--%3E%20VALIDATING%20%3A%20start%20validation%0A%20%20%20%20VALIDATING%20--%3E%20READY%20%3A%20required%20gates%20passed%0A%20%20%20%20VALIDATING%20--%3E%20FAILED%20%3A%20validation%20failed%20(reason%20required)%0A%20%20%20%20READY%20--%3E%20APPROVAL_PENDING%20%3A%20approval%20chain%20starts%0A%20%20%20%20APPROVAL_PENDING%20--%3E%20APPROVED%20%3A%20chain%20satisfied%0A%20%20%20%20APPROVED%20--%3E%20DEPLOYING%20%3A%20deploy%20to%20the%20starting%20ring%0A%20%20%20%20DEPLOYING%20--%3E%20ACTIVE%20%3A%20serving%20the%20ring's%20audience%0A%20%20%20%20DEPLOYING%20--%3E%20FAILED%20%3A%20deploy%20failed%20(reason%20required)%0A%20%20%20%20ACTIVE%20--%3E%20PROMOTED%20%3A%20final%20ring%20reached%20for%20every%20target%0A%20%20%20%20ACTIVE%20--%3E%20ROLLED_BACK%20%3A%20pulled%20back%20(reason%20required)%0A%20%20%20%20PROMOTED%20--%3E%20COMPLETED%20%3A%20closed%20out%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=p('<p>Eleven edges, three terminal states: <code>FAILED</code>, <code>ROLLED_BACK</code>, and <code>COMPLETED</code>. No state exits a terminal, no state re-enters itself, and no state re-opens artifact mutation — the artifact set freezes the moment the release is created.</p><h2 id="what-each-stage-means" tabindex="-1">What each stage means <a class="header-anchor" href="#what-each-stage-means" aria-label="Permalink to &quot;What each stage means&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>What is true</th></tr></thead><tbody><tr><td><code>DRAFT</code></td><td>The release exists: version, artifacts, ring, and targets are pinned. Creation already validates that every artifact is <code>READY</code>, belongs to the version, and that every target tenant holds the application.</td></tr><tr><td><code>VALIDATING</code></td><td>Quality gates instantiate for the release&#39;s ring. A required gate that has not passed (or has no data yet) refuses the crossing to <code>READY</code>.</td></tr><tr><td><code>READY</code></td><td>The artifact-and-gate side is settled. The approval leg can begin.</td></tr><tr><td><code>APPROVAL_PENDING</code></td><td>The resolved approval workflow runs its rounds. A satisfied round lets the crossing fire; a rejected round holds the release here until rework.</td></tr><tr><td><code>APPROVED</code></td><td>Every gate of governance has passed. The frozen manifest is written at this exact crossing — the immutable record of what ships, to whom, under which approvals.</td></tr><tr><td><code>DEPLOYING</code></td><td>Distribution is being driven to the starting ring&#39;s audience.</td></tr><tr><td><code>ACTIVE</code></td><td>The release serves its audience. Downloads flow; feedback and metrics accumulate.</td></tr><tr><td><code>PROMOTED</code></td><td>Every target has reached the final ring. Hops may already have widened distribution ring by ring.</td></tr><tr><td><code>ROLLED_BACK</code></td><td>Terminal. The one-action rollback pulled the release: direct downloads are cut, store assignments reverted, channel records rolled back — while artifacts and history stay untouched.</td></tr><tr><td><code>COMPLETED</code></td><td>Terminal. The operator&#39;s explicit close-out after <code>PROMOTED</code>.</td></tr><tr><td><code>FAILED</code></td><td>Terminal, with a mandatory recorded reason.</td></tr></tbody></table><h2 id="the-rules-that-make-it-trustworthy" tabindex="-1">The rules that make it trustworthy <a class="header-anchor" href="#the-rules-that-make-it-trustworthy" aria-label="Permalink to &quot;The rules that make it trustworthy&quot;">​</a></h2><ul><li><strong>Reasons are mandatory on the dark edges.</strong> A release that fails or is rolled back explains itself; the reason rides both the timeline and the audit event.</li><li><strong>Transitions are compare-and-set.</strong> Two racing crossings can never both commit; the loser re-reads and answers a precise conflict (<code>RELEASE_TRANSITION_INVALID</code>, carrying the current and attempted states).</li><li><strong>Every crossing is history.</strong> Each committed transition appends one append-only timeline row — actor, from, to, reason, timestamp. The release dashboard renders this timeline; nothing is ever rewritten.</li><li><strong>Policy engines guard the crossings.</strong> The approval engine refuses <code>APPROVED</code> while a round is pending or rejected; quality gates refuse <code>READY</code> while a required gate is unpassed. Policies can refuse; they can never widen the machine.</li><li><strong>A failed release never re-enters the machine.</strong> Its artifacts cannot be fixed in place — the fix path is a new version with corrected artifacts and a new release. The failure and its reason stay as permanent history.</li><li><strong>Rollback never deletes.</strong> A rolled-back version, its artifacts, and the release&#39;s whole history stay readable; downloads are simply refused from then on. The portal shows what was pulled — it just will not serve it again.</li></ul><h2 id="the-frozen-manifest" tabindex="-1">The frozen manifest <a class="header-anchor" href="#the-frozen-manifest" aria-label="Permalink to &quot;The frozen manifest&quot;">​</a></h2><p>At the <code>APPROVED</code> crossing, ShipperDog writes the release manifest: a complete, immutable document of what ships — artifacts pinned by content (SHA-256, build number, size, filename), the target set with group selections, the ring, the environment and its resolved configuration, and the satisfied approval chain. It answers the compliance question — &quot;exactly what did this tenant receive on this date?&quot; — from its own stored bytes, carries a content digest, and is served as JSON or YAML. Two approved releases of the same application can be diffed artifact-by-artifact.</p><h2 id="where-to-go-deeper" tabindex="-1">Where to go deeper <a class="header-anchor" href="#where-to-go-deeper" aria-label="Permalink to &quot;Where to go deeper&quot;">​</a></h2><ul><li><a href="/shipperdog/snapshot/concepts/approvals-gates">Approvals and gates</a> — the engines that guard two of these crossings</li><li><a href="/shipperdog/snapshot/concepts/rings-and-rollout">Rings and rollout</a> — what happens between <code>ACTIVE</code> and <code>PROMOTED</code></li><li><a href="/shipperdog/snapshot/concepts/ota-updates">OTA updates</a> — OTA-channel releases ride this same machine, one signed bundle per release</li><li>Developer detail: the <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/releases.md" target="_blank" rel="noreferrer">releases</a> module doc (model, transitions API, manifest, promotion engine).</li></ul>',9))])}const y=i(f,[["render",m]]);export{b as __pageData,y as default};
